    .mx_IconizedContextMenu_checked::before {
        mask-image: url('$(res)/img/element-icons/roomlist/checkmark.svg');
    }

    .mx_IconizedContextMenu_unchecked::before {
        content: unset;
    }

    .mx_IconizedContextMenu_sublabel {
        margin-left: 20px;
        color: $tertiary-content;
    }
