import React from "react";

import { ContextMenuButton } from "../../structures/ContextMenu";
import { useContextMenu } from "../../structures/ContextMenu";
import IconizedContextMenu, { IconizedContextMenuOptionList } from "./IconizedContextMenu";

interface Props extends Omit<React.ComponentProps<typeof ContextMenuButton>, "onClick" | "isExpanded" | "label"> {
    options: React.ReactNode[];
    title: string;
}

export const KebabContextMenu: React.FC<Props> = ({ options, title, disabled, ...props }) => {
    const [isOpen, button, open, close] = useContextMenu<HTMLButtonElement>();
    const rect = isOpen ? button.current?.getBoundingClientRect() : undefined;
    const openMenu = (event: React.SyntheticEvent) => {
        button.current?.focus();
        open(event);
    };

    // AccessibleButton invokes option callbacks for keyboard activation as well as clicks.
    // The menu's click handler covers pointer interaction; this wrapper also closes it for Enter and Space.
    const menuOptions = options.map((option, index) => {
        if (!React.isValidElement<{ onClick?: (event: React.SyntheticEvent) => void }>(option)) return option;
        return React.cloneElement(option, {
            key: option.key ?? index,
            onClick: (event: React.SyntheticEvent) => {
                try {
                    option.props.onClick?.(event);
                } finally {
                    close();
                }
            },
        });
    });

    return <>
        <ContextMenuButton
            {...props}
            element="button"
            type="button"
            inputRef={button}
            className="mx_KebabContextMenu"
            label={title}
            isExpanded={isOpen}
            disabled={disabled}
            aria-disabled={!!disabled}
            onClick={openMenu}
        >
            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
        </ContextMenuButton>
        { isOpen && rect && <IconizedContextMenu
            top={rect.bottom + window.scrollY}
            right={window.innerWidth - rect.right - window.scrollX}
            rightAligned
            onFinished={close}
        >
            <IconizedContextMenuOptionList first>
                { menuOptions }
            </IconizedContextMenuOptionList>
        </IconizedContextMenu> }
    </>;
};

